SELECT  FROM sol_requirement_analysis_revision
WHERE deleted = b'0' AND tenant_id = #{query.tenantId} AND entity_id = #{query.entityId}
ORDER BY revision_no DESC LIMIT 1

SELECT  FROM sol_requirement_analysis_revision
WHERE deleted = b'0' AND tenant_id = #{query.tenantId} AND entity_id = #{query.entityId} AND revision_state = 'FROZEN'
AND revision_no < #{query.beforeRevisionNo}
ORDER BY revision_no DESC LIMIT #{query.limit}

SELECT id FROM sol_requirement_analysis_revision
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId} AND deleted=0
  AND revision_state = 'FROZEN'
AND effective_marker=1
AND id > #{query.afterId}



            AND entity_id IN #{id}

        AND 1=0


ORDER BY id ASC LIMIT #{query.limit}
